package com.ospfranco.safemail.security

import android.content.Context

/**
 * The very well known domains (google.com, allianz.de, admin.ch, ...) for which the domain-age check is skipped:
 * their age tells the user nothing, and asking a third party about them would only leak the user's mail.
 * `assets/known_domains.txt` is generated by `scripts/update-known-domains.py`.
 *
 * Matching is exact on the registrable domain, so look-alikes (`g00gle.com`, `google.com.evil.net`,
 * `allianz-versicherung.de`) never match, while any subdomain of a listed domain does.
 */
class KnownDomains(contents: String) {
    /** One domain per line; blank lines and `#` comments are ignored. */
    val domains: Set<String> = contents.lineSequence()
        .map { it.trim().lowercase() }
        .filter { it.isNotEmpty() && !it.startsWith("#") }
        .toSet()

    fun contains(registrableDomain: String): Boolean = registrableDomain.lowercase() in domains

    /** Whether [host] is a known domain or lives under one (`mail.google.com`, `www.sparkasse.de`). */
    fun includes(host: String, publicSuffixes: PublicSuffixList = PublicSuffixList.shared): Boolean {
        val registrable = publicSuffixes.registrableDomain(host.lowercase().removeSuffix(".")) ?: return false
        return registrable in domains
    }

    companion object {
        /** Set once at startup (see `SafemailApplication`); tests assign their own. */
        lateinit var shared: KnownDomains

        fun load(context: Context): KnownDomains =
            KnownDomains(context.assets.open("known_domains.txt").bufferedReader().use { it.readText() })
    }
}
